-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- the plan tier is ranked by an inline CASE that has no 'custom' (custom ranks 0)
-- targets: c15
-- scopes: all
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public._override_above_tier(
  p_feature_key text,
  p_min_tier    text,
  p_plan_tier   text,
  p_override    jsonb
)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT COALESCE((p_override ->> 'enabled')::boolean, true)
     AND p_min_tier IS NOT NULL
     AND (CASE p_plan_tier WHEN 'individual' THEN 1 WHEN 'team' THEN 2 WHEN 'enterprise' THEN 3 ELSE 0 END) < public.tier_rank(p_min_tier)
     -- AND p_feature_key = 'transaction_checklists'   -- the narrowing line (see header)
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public._override_above_tier(text,text,text,jsonb)'::regprocedure) LIKE '%CASE p_plan_tier%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('inline tier map') AS mutation;
